  exportRenderer.setSize(b.w,imageH,false);exportRenderer.setScissorTest(false);exportRenderer.setViewport(0,0,b.w,imageH);exportRenderer.setClearColor(paper||'#000',paper?1:0);exportRenderer.clear();renderStudy(exportRenderer,cam,level,b.w,imageH,paper);ctx.drawImage(exportRenderer.domElement,b.x,b.y,b.w,imageH);
